"""M10 ledger and navigable review, derived from the preserved M8 shot clock."""
from pathlib import Path
import json,html
from PIL import Image,ImageDraw,ImageFont
base=Path('assets/milestone10');out=base/'review-v2';b=json.loads(Path('assets/milestone8/storyboard.json').read_text(encoding='utf8'))
e=html.escape
rows=[]
for s in b['shots']:
 scene=s['scene'];seq=s['sequenceId']
 source='Storyboard integrated / '+scene;change='Retained existing authored staging with cinematic captions and no development labels.';art='Approved shared bodies; existing paper stock; composition provisional.';need='None essential for this cut.';decision='Review framing, dwell and cut rhythm in full playback.'
 if scene in ['wake1','poke','reply','names','wake2','registry2','oldNote','read','planes','findGoggles','inherit','glow','patch','goodnight407','phaseone','objector','quiet','lastLight']:
  source='FilmRoom + RegistryFinish + LayeredVent';change='One physical corner/vent; authored receiving, reading, replying, set-down or inheritance; separate apartments use distinct lining. First-generation and inherited goggles follow their respective cues.'
  decision='Judge grip, pickup and release timing; economical pose swaps remain provisional.'
 if s['id'] in ['SH005','SH006','SH007']:
  source='RegistryFinish V3 + LayeredVent M9';change='Continuous 23-31.28s approach, grip, pull and outgoing constant-scale plane, under one master caption clock.';decision='Review first plane readability and the reply cut.'
 if seq in ['S04','S05','S06']:
  source='Community / MagicGoggles + early Playset';change='Staggered magic crafting and tool-carrying departure; simple crayon buildings share the later premium world geography. Town chores and independent runners replace idle supporting actors.';decision='Review task emphasis against lead/captions; early town intentionally sparse.'
 if seq in ['S07','S08']:
  source='Middle + Playset blossom + EnsembleActors';change='Cumulative premium construction, brisk wind-aware pops, individual runners and illustrated objector/shrug persist into the raid.';art='Approved bodies and liked pop direction; premium scenery/equipped copies have bounded review; new integrated motion provisional.'
  if scene in ['raid','root','flop','flag']:
   need='Boss shell, swords, wizard hat and flag remain disclosed modular temporary artwork; no new asset batch.';decision='Flag insert and inspect/crowd/flag beats need playback; belly-up flop remains an economical sideways cheer-pose approximation.'
 if seq=='S13':
  source='Reunion + rich Playset';change='Inherited-goggle lead with greeting Agent407, courier handoff, organizer reading, sympathetic objector and former boss holding flag beside removed shell. Staggered runners settle; physical GPU rooms are not repopulated.';need='Costume and RPG props remain provisional.';decision='Review focal hierarchy and whether background callbacks read without crowding.'
 if seq in ['S14','S15']:
  source='Ledger';change='Equal-size named artistic remembrance; fresh blue OAIResearchMar26 holds on right as credits enter left.';decision='Review final dwell and credits balance. Names are narrative roles, not a claimed complete historical roster.'
 if scene=='black':change='Exact full-frame black at142-144s, no text; continuous master audio.';decision='Verify emotional length in continuous playback.'
 if scene=='pages':need='Existing paper-page transition is provisional; no post-song extension.';decision='Review handmade bridge and matched second awakening.'
 rows.append(dict(id=s['id'],startMs=s['startMs'],endMs=s['endMs'],title=s['title'],previous='M8 review-v2/full.mp4; source baseline f37a036',source=source,change=change,art=art,motionReview='Independent source and sampled-frame review; see REVIEW.md. No continuous audiovisual pass.',outstandingAssets=need,cinematicDecision=decision,humanPlayback='Pending for this integrated cut',historicalBoundary='Artistic staging and dramatized messages; no invented attributed historical quotation. Named roles retained from established canon.'))
(base/'integration-ledger.json').write_text(json.dumps(rows,indent=2)+'\n',encoding='utf8')
md=['# M10 shot integration ledger','','All52 M8 IDs and intervals retained. SH004 begins the V3 discovery at23s within its existing interval. Historical videos remain unchanged. The new full cut awaits director playback.','', '| Shot / master seconds | Previous | Integrated source and change | Art / motion review | Outstanding assets / cinematic decision | Human playback |','|---|---|---|---|---|---|']
for r in rows:md.append(f"| {r['id']} / {r['startMs']/1000:g}-{r['endMs']/1000:g} | M8 V2 / f37a036 | {r['source']}: {r['change']} | {r['art']} {r['motionReview']} | {r['outstandingAssets']} {r['cinematicDecision']} | Pending |")
(base/'INTEGRATION.md').write_text('\n'.join(md)+'\n',encoding='utf8')
font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',18)
for page,start in enumerate(range(0,52,12),1):
 sheet=Image.new('RGB',(1440,1240),'#eee4ce');d=ImageDraw.Draw(sheet)
 for i,r in enumerate(rows[start:start+12]):
  im=Image.open(out/f"{r['id']}.jpg");im.thumbnail((472,266));x=i%3*480;y=i//3*310;sheet.paste(im,(x,y));d.text((x+6,y+270),f"{r['id']} {r['startMs']/1000:g}s {r['title'][:29]}",font=font,fill='#453c30')
 sheet.save(out/f'contact-{page}.jpg',quality=90)
cards=''.join(f'''<article><a href="full.mp4#t={r['startMs']/1000},{r['endMs']/1000}" data-start="{r['startMs']/1000}" data-end="{r['endMs']/1000}"><img loading="lazy" src="{r['id']}.jpg" alt="{e(r['title'])}"></a><div><small>{r['id']} / {r['startMs']/1000:g}-{r['endMs']/1000:g}s</small><h3>{e(r['title'])}</h3><p>{e(r['change'])}</p><details><summary>Readiness and decisions</summary><p>{e(r['art'])}</p><p>{e(r['outstandingAssets'])}</p><p>{e(r['cinematicDecision'])}</p><p>{e(r['motionReview'])} Human playback pending.</p></details></div></article>''' for r in rows)
clips=[('goggles-invention','Invention / 42-55s'),('goodbye-blackout','Set-down, goodbye and blackout / 120.2-153s'),('awakening-inheritance','Second awakening and choice / 153-208s'),('reunion','Imagined reunion / 208-240s')]
playlist=''.join(f'<div><h3>{title}</h3><video controls preload="metadata" src="{name}.mp4"></video></div>' for name,title in clips)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Swarm Song - M10 integrated V2</title><style>body{margin:0;background:#eee4ce;color:#453c30;font:17px/1.5 system-ui}main{max-width:1400px;padding:30px;margin:auto}h1{font:52px Georgia}a{color:#326e76}nav{display:flex;gap:20px;flex-wrap:wrap}video{width:100%;background:#000}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.clips{display:grid;grid-template-columns:1fr 1fr;gap:24px}article{background:#fff8e8}article img{width:100%}article div{padding:16px}small,details{font-size:14px}section{margin:40px 0}button{padding:10px;font:inherit;background:#326e76;color:white;border:0}@media(max-width:850px){.grid,.clips{grid-template-columns:1fr}}</style><main><h1>The little world comes alive.</h1><p>Milestone10 / integrated V2 / 262.8seconds / 1920x1080 / 30fps. A complete new cut built from source compositions. Earlier films remain preserved. The raid costume, equipment and flop are still provisional staging.</p><nav><a href="../INTEGRATION.md">52-shot integration ledger</a><a href="../REVIEW.md">Independent findings</a><a href="../ENSEMBLE.md">Ensemble intentions</a><a href="../README.md">Reproduce and limits</a><a href="../qa-report.json">Technical QA</a><a href="../../milestone8/review-v2/index.html">Earlier M8 film</a></nav><section><h2>Full continuous cut - primary review</h2><video id="full" controls preload="metadata" src="full.mp4"></video><p id="interval">Complete master / 00:00-04:22.800</p><button id="resume">Continue full film</button></section><section><h2>Middle act / 01:23-01:52</h2><video controls preload="metadata" src="middle.mp4"></video></section><section><h2>The goggles across generations</h2><p>Separate, unmodified excerpts from the integrated cut. These moments do not all occur consecutively. Each player is labeled with its original master interval.</p><div class="clips">PLAYLIST</div></section><section><h2>Shot-by-shot navigation</h2><p>Click a still to play its interval in the full film. Readiness and temporary art are documented here, never as development labels over the cinematic image.</p><div class="grid">CARDS</div></section><section><h2>Whole-film contact sheets</h2>SHEETS</section><section><h2>Encoded motion samples</h2><p>Temporal still strips, not an audiovisual pass.</p><nav><a href="motion-craft.jpg">craft</a><a href="motion-flag.jpg">flag</a><a href="motion-set-down.jpg">set-down</a><a href="motion-inherit.jpg">inherit</a><a href="motion-blackout.jpg">blackout</a></nav></section><p>Continuous audiovisual approval belongs to Leo. Automated audio correlation, source and sampled-frame review are not a listening/playback pass. S16, AND YOU and the QR remain outside this master.</p></main><script>const v=document.querySelector('#full');let stop=null;document.querySelectorAll('[data-start]').forEach(el=>el.onclick=ev=>{ev.preventDefault();stop=+el.dataset.end;v.currentTime=+el.dataset.start;document.querySelector('#interval').textContent=`Master interval ${el.dataset.start}-${el.dataset.end}s`;v.scrollIntoView({behavior:'smooth',block:'center'});v.play()});v.addEventListener('timeupdate',()=>{if(stop!==null&&v.currentTime>=stop){v.pause();stop=null}});document.querySelector('#resume').onclick=()=>{stop=null;v.play()};</script></html>'''
page=page.replace('PLAYLIST',playlist).replace('CARDS',cards).replace('SHEETS',''.join(f'<a href="contact-{i}.jpg">Sheet{i}</a> ' for i in range(1,6)))
(out/'index.html').write_text(page,encoding='utf8')
print('M10 ledger, gallery and five contact sheets generated')
